import { LOADER_RUN, KSTAGE, KRILL_RT_LEN, KRILL_RT_AT, KRILL_RESIDENT_AT } from './loader-src.mjs';
import { END_DST, IEND_NAME, IEND_RUN, buildEnding } from './ending-src.mjs';

