const planPats = !PLAN ? []
  : PLAN === 2 ? planData.paired.codes.map(c => c[0])
  : PLAN === 3 ? planData.fine.codes
  : planData.codes;
const nearestCode = p => { let bi = 0, bd = 99;
  planPats.forEach((q, i) => { const d = planL1(p, q); if (d < bd) { bd = d; bi = i; } });
  return 2 + bi; };
