const ecPatch = () => [0, 1, 2, 3].map(k => (k === 0 ? '        ldx baseHi\n' : '        inx\n') +
  EC_SITES.filter(([, p]) => p === k).map(([l]) => `        stx ${l}+2`).join('\n')).join('\n');
// kTab[R] = K + 148 (see the unsigned clamp tables): the generic chooser's index is h' + kTab[R],
// h' capped, into ecMT/ecM16/ecM8. Screen rows 8R + 56 (h' <= 100: at most 252), tail 48 - 8i.
const kTab = [...Array(13)].map((_, R) => 8 * R - 92 + ECOFF)
  .concat(FALLTAIL ? [...Array(FTROWS)].map((_, i) => 8 * (-1 - i) - 92 + ECOFF) : []);
if (kTab.some(k => k < 0 || k > 255)) throw new Error('kTab out of 0..255');
// per cell-row: cell is fully solid when min height >= t1, fully blank when max < tb.
// fill = h + 8R - 92, so solid at fill>=8 and blank at fill<=0.
const t1Tab = [], tbTab = [];
for (let R = 0; R < 13; R++) { t1Tab.push(100 - 8 * R); tbTab.push(Math.max(0, 93 - 8 * R)); }
// ...and FALLTAIL's five rows BELOW the screen, which are cell rows -1..-5: 108..140 and
// 101..133. Without these every cell went to rfEdgeL, which is only valid for cells that
// actually contain the boundary -- so blank floor picked up a ramp glyph and the whole width
// rose as rows of dots.
const ftT1 = [], ftTb = [];
if (FALLTAIL) for (let i = 1; i <= FTROWS; i++) { ftT1.push(100 + 8 * i); ftTb.push(93 + 8 * i); }
const rowLo = [], rowHi = []; for (let R = 0; R < 25; R++) { rowLo.push((R * 40) & 255); rowHi.push((R * 40) >> 8); }

// ---- diagnostic knobs ----
// Read every knob through flag()/hexArg() so DIAG lists exactly the ones in force. Two
// things depend on knowing that: the build must not overwrite the tracked iray.asm with a
// throwaway configuration (see the write site at the bottom), and the "ok:" line has to
// say out loud which knobs are on -- NORAY and NOFILL in particular produce a build that
// renders faster-looking nonsense and have already been mistaken for a real measurement.
const DIAG = [...DIAGEARLY];
const flag = n => { const on = process.env[n] === '1'; if (on) DIAG.push(n); return on; };
const hexArg = (n, dflt, mask) => {
  if (process.env[n] === undefined) return dflt;
  DIAG.push(`${n}=${process.env[n]}`);
  return parseInt(process.env[n], 16) & mask;
};

const MEASURE = flag('MEASURE');
// SPIN=1: hold the turn key. One pose, one control, no translation -- the only benchmark move
// that sweeps all 256 cast angles and the only one that cannot bump a wall. See spinStep.
const SPIN = flag('SPIN');
const NORAY = flag('NORAY');   // skip marching/subdivision
const NOFILL = flag('NOFILL'); // skip renderSym (fill)
// DUMPH: print colH as hex over the top 8 rows, so the interpolated heights can be read
// straight off a screenshot. The VICE monitor's checkpoint/bsave route does not survive
// -autostart here, and inferring colH from drawn pixels cannot see values above 100.
const DUMPH = flag('DUMPH');
// static start angle, e.g. PA=4f. Angle-dependent glitches are far easier to pin here than
// under SPIN -- a fixed angle makes the frame reproducible, so a plain -exitscreenshot run
// is comparable across builds without breakpointing the frame counter.
// Level 2 starts you on the SOUTH arc facing west along it -- see PX/PY below for why there.
// ---- where each level STARTS ----
// Per level, not per build: dieKey restarts with "jmp entry", and lvlMeT is RAM, so after dying
// on level 4 the boot used to place you at the BUILD's start -- level 1's (2.5, 2.5) -- on level
// 4's map, which is inside a wall. lvlStart reads the live level instead, so a death always
// returns you to the official start point of the level you died on.
const LEVEL_START = {
  1: [0x0280, 0x0280, 0x19, 0xc0],
  2: [0x046e, 0x07dc, 0xdb, 0x00],   // the user's spot, 2026-09-22
  3: [0x0180, 0x0180, 0x20, 0x00],
  4: [0x0380, 0x0480, 0x00, 0x00],   // the hub: the player's cell (3,4), facing the three holes
  5: [0x0180, 0x0880, 0x00, 0x00],   // (1.5, 8.5), the west end of the hall, facing east
  6: [0x0180, 0x0780, 0xc0, 0x00],   // (1.5, 7.5) facing NORTH, straight at the exit one cell away
  7: [0x0780, 0x0a80, 0xc0, 0x00],   // (7.5, 10.5) facing NORTH, the idol two cells ahead
  8: [0x0180, 0x0180, 0x00, 0x00],   // (1.5, 1.5), the maze's corner, facing east
};
const ST0 = LEVEL_START[LVL] ?? LEVEL_START[1];
const startOf = n => n === LVL ? [PX, PY, PA, PAF] : (LEVEL_START[n] ?? LEVEL_START[1]);
// ---- every declared cell must be an OPEN cell of its OWN level's map ----
// Level 5 was redesigned from 14x14 to 6x6 and this table still said (1.5, 8.5): the player
// spawned off the edge of the map, in a room that rendered as two flat colours. The same shape
// of mistake put the player inside a wall when 6 and 7 were built as level 1 by mistake. Both
// are one comparison to catch, and neither is visible in a build log.
// LEVEL_START, not the PX/PY overrides: a diagnostic pose is free to be anywhere, but the pose
// a level SHIPS with is data, and data gets checked.
for (const n of ALLLVL) {
  const m = MAP_OF(n);
  for (const [what, xy] of [['start', LEVEL_START[n] && [LEVEL_START[n][0] / 256, LEVEL_START[n][1] / 256]],
                            ['idol', LEVEL_IDOL[n]]]) {
    if (!xy) continue;
    const cx = Math.floor(xy[0]), cy = Math.floor(xy[1]);
    const ok = cy >= 0 && cy < m.length && cx >= 0 && cx < m[cy].length && m[cy][cx] !== '#';
    if (!ok) throw new Error(`level ${n}'s ${what} is at cell (${cx},${cy}), which is ` +
      (cy >= m.length || cx >= (m[0]?.length ?? 0) ? `outside its ${m[0]?.length}x${m.length} map`
                                                   : 'a solid wall'));
  }
}
const PA = hexArg('PA', ST0[2], 0xff);   // L3: the diagonal, at the orb   // L1: $19c0 with PAF, the user's choice after playing --
                                                                    // COMBO2: $19c0 with PAF, the user's choice after playing -- from (2,2) toward the
                                                                    //   room's far wall and the corridor mouth
// PAF: the LOW byte of the 16-bit angle, which the HUD does not show. Not a nicety -- paq indexes
// the ray tables at QUARTER-unit resolution, so pa:paF = C000, C040, C080 and C0C0 are four
// DIFFERENT renders that all read "AC0" on screen. A cold start left paF at zero, so three of
// every four reachable views could not be replayed from a screenshot at all, and a reported
// glitch that lived on one of them looked like it simply did not reproduce.
const PAF = hexArg('PAF', ST0[3], 0xff);
// PX/PY: exact 8.8 start position, matching the on-screen readout's cell.frac hex
// (e.g. the readout showing X=273 is PX=273). Lets a screenshot be replayed exactly.
// Level 1 opens in the room's north-west corner looking diagonally across it. The old start
// (2.5, 1.5 facing along +x) put a wall a cell in front of the camera once the room's walls
// were stepped in, so the game began on a near-black screen.
// Chosen for the opening FRAME RATE as much as the composition: this angle shows the room
// without also looking straight down the full corridor, so it opens at 20 fps rather than the
// 12 of the corridor-axis view. First impressions run on the first frame.
// Level 2 opens at (6.5, 7.5): the ring cell DIAMETRICALLY OPPOSITE the door, 15 of the ring's
// 30 cells away either way round. That is the user's call after playing the first cut, where the
// start sat near the door and the angel idled on the far arc -- you met it once as a surprise and
// then simply walked back and finished the level without it ever mattering again. Starting
// opposite, with the angel ON the door, means every route to the goal has the angel somewhere
// along it, and the tie means it has no preferred arc until the player picks one.
const PX = hexArg('PX', ST0[0], 0xffff);   // PP at (2,2) in levels 1 and 2, (1,1) in 3-5
const PY = hexArg('PY', ST0[1], 0xffff);
// Angle units per TICK while the joystick is held, in 1/256ths of a unit. Turning is
// accumulated at that precision because the rate is well under one unit a tick: pa is the
// high byte of a 16-bit angle and paF the low, so the fraction carries between frames
// instead of being lost. 3/4 of a unit per tick * 60 ticks = 45 units a second = 63 degrees.
//
// ---- what makes a turn rate smooth, and why this one is not special ----
// The renderer draws the angle at QUARTER-unit resolution (FINEANG's 1024-entry tables, fed
// by paq -- see the paq block in the frame setup, which used to discard the fraction and is
// the reason turning ever stuttered). One quarter unit is 0.75 screen columns at the centre
// of the view and 1.06 at the edge, so the WORST a frame can be out is about one column --
// under what the renderer can draw, whatever rate is chosen. A whole unit is 3.0 and 4.3
// columns, which is why the old byte-resolution path was plainly uneven at any rate below
// 256 (one unit a tick, 84 deg/s) that did not divide the frame time exactly.
//
